<script setup lang="ts">
import introductionData from '@/data/about.json'

interface DesignItem {
  title: string
  description: string
}
interface RefCategory {
  category?: string
  references?: string[]
}
interface AchievementGroup {
  title: string
  content: { time: string; description: string }[]
}
interface Milestone {
  time: string
  description: string
}

const introduction = introductionData as { title: string; content: unknown }[]

/** 简单 Markdown：**粗体**、[文本](url)、段落与换行；「」仅作引号展示，不加粗 */
function renderMarkdown(text: string): string {
  if (!text) return ''
  let s = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  s = s.replace(
    /\[([^\]]+)\]\(([^)]+)\)/g,
    '<a href="$2" target="_blank" rel="noopener" class="about-link">$1</a>'
  )
  s = s.replace(/\n\n/g, '</p><p>')
  s = s.replace(/\n/g, '<br/>')
  return '<p>' + s + '</p>'
}
</script>

